import { readFileSync } from 'node:fs';

const PER_MILLION = 1_000_000;
const DAY_MS = 86_400_000;
const FIELDS = ['input', 'output', 'cacheWrite5m', 'cacheWrite1h', 'cacheRead'];

// Keys starting with "_" (_asOf, _note) are metadata, not models.
export function loadPrices(overrides = {}) {
  const shipped = JSON.parse(readFileSync(new URL('./prices.json', import.meta.url), 'utf8'));
  return Object.fromEntries(Object.entries({ ...shipped, ...overrides }).filter(([k]) => !k.startsWith('_')));
}

// "claude-opus-5-5-20261001" matches key "claude-opus-5-5"; the longest key wins over "claude-opus-5".
export function priceFor(model, prices) {
  let best = null;
  for (const key of Object.keys(prices)) {
    if ((model === key || model.startsWith(`${key}-`)) && (best === null || key.length > best.length)) best = key;
  }
  return best === null ? null : prices[best];
}

export function costOf(rows, prices) {
  let usd = 0;
  const unpriced = new Set();
  for (const row of rows) {
    const price = priceFor(row.model ?? '', prices);
    if (!price) {
      unpriced.add(row.model ?? 'unknown');
      continue;
    }
    for (const field of FIELDS) usd += ((row[field] ?? 0) * (price[field] ?? 0)) / PER_MILLION;
  }
  return { usd, unpriced: [...unpriced] };
}

// "Today" starts at midnight on the owner's own clock; 7 and 30 days are rolling windows back from now.
export function spendWindows(rows, now, prices = loadPrices()) {
  const dayStart = Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), now.getUTCDate());
  const cutoffs = { today: dayStart, d7: now.getTime() - 7 * DAY_MS, d30: now.getTime() - 30 * DAY_MS };
  const out = {};
  for (const [name, from] of Object.entries(cutoffs)) {
    out[name] = costOf(rows.filter((r) => Date.parse(r.ts) >= from), prices).usd;
  }
  return out;
}

// What the owner hid from the map: conversations removed from session-map and cut-offs dismissed from the panel.
// Only session-map's own folder is written; Claude Code's transcripts and the projects are never touched.
import { join } from 'node:path';
import { readJsonFile, writeAtomic } from './store.mjs';

const REMOVED = 'removed.json';
const DISMISSED = 'cut-dismissed.json';

const isPlainObject = (v) => v !== null && typeof v === 'object' && !Array.isArray(v);

// Removed for good: the same shape as archived.json, a list of session ids.
export function readRemoved(smDir) {
  const stored = readJsonFile(join(smDir, REMOVED), []);
  return new Set(Array.isArray(stored) ? stored.filter((id) => typeof id === 'string') : []);
}

export function addRemoved(smDir, sessionId) {
  const ids = readRemoved(smDir);
  if (ids.has(sessionId)) return;
  ids.add(sessionId);
  writeAtomic(join(smDir, REMOVED), `${JSON.stringify([...ids])}\n`);
}

// sessionId → the last activity it had when dismissed; cut off again later (a newer activity), it comes back.
export function readDismissed(smDir) {
  const stored = readJsonFile(join(smDir, DISMISSED), {});
  return isPlainObject(stored) ? stored : {};
}

export function dismissCut(smDir, sessionId, at) {
  const dismissed = readDismissed(smDir);
  dismissed[sessionId] = at;
  writeAtomic(join(smDir, DISMISSED), `${JSON.stringify(dismissed)}\n`);
}

import { realpathSync } from 'node:fs';
import { readFile, stat } from 'node:fs/promises';
import { isAbsolute, relative, resolve, sep } from 'node:path';

export const FILE_MAX = 1024 * 1024;
const GIT_NAME_RE = /^(\.git|git~\d+)$/i;
const ENV_RE = /^\.env(\..+)?$/i;
const ENV_TEMPLATE_RE = /\.(example|sample|template|dist)$/i;

const looksBinary = (buf) => buf.subarray(0, 8000).includes(0);
const lineCount = (text) => (text.match(/\n/g)?.length ?? 0) + (text && !text.endsWith('\n') ? 1 : 0);

// True when path lies below root (root itself does not count) and outside its .git folder.
const isBelow = (root, path) => {
  const rel = relative(root, path);
  return rel !== '' && !isAbsolute(rel) && !rel.split(sep).some((s) => GIT_NAME_RE.test(s));
};

// The absolute path of a file under root, or null. rel comes from the page, so it may try to climb out of the
// project; a link that leads out of the root is refused by following it.
export function resolveInside(root, rel) {
  if (typeof rel !== 'string' || !rel || rel.includes('\0')) return null;
  const abs = resolve(root, rel);
  if (!isBelow(root, abs)) return null;
  let real;
  try {
    real = realpathSync(abs);
  } catch {
    return abs;
  }
  return isBelow(realpathSync(root), real) ? real : null;
}

export async function readForView(root, rel) {
  const abs = resolveInside(root, rel);
  if (!abs) return { ok: false, error: 'bad-path' };
  const name = abs.split(/[\\/]/).pop();
  if (ENV_RE.test(name) && !ENV_TEMPLATE_RE.test(name)) return { ok: false, error: 'sensitive' };
  const info = await stat(abs).catch(() => null);
  if (!info?.isFile()) return { ok: false, error: 'not-found' };
  if (info.size > FILE_MAX) return { ok: false, error: 'too-large' };
  const buf = await readFile(abs);
  if (looksBinary(buf)) return { ok: false, error: 'binary' };
  const text = buf.toString('utf8');
  return { ok: true, text, lines: lineCount(text) };
}

import { log } from '../log.mjs';
import { redact } from './redact.mjs';
import { extractJSON } from './runner.mjs';

const TIMEOUT_MS = 60_000;
const MAX_TOKENS = 1024;

const withHint = (prompt, schemaHint) => (schemaHint ? `${prompt}\n\nReply with one JSON object only, no prose, shaped like:\n${schemaHint}\n` : prompt);

// provider: one entry of the catalog ({id, endpoint, defaultModel}). Same shape as runClaudeJSON, plus who answered.
// Failures are short codes in the log and in the result: never the key, a header or the body of the reply.
export async function askProvider(prompt, { provider, model, key, schemaHint, fetchFn = fetch, timeoutMs = TIMEOUT_MS } = {}) {
  const fail = (error, detail = {}) => {
    log('warn', 'ai-api-failed', { provider: provider.id, error, ...detail });
    return { ok: false, error, provider: provider.id };
  };
  if (typeof key !== 'string' || !key) return fail('no-key');
  const usedModel = model || provider.defaultModel;
  const headers = { Authorization: `Bearer ${key}`, 'Content-Type': 'application/json', 'X-Title': 'session-map' };
  const body = {
    model: usedModel,
    messages: [{ role: 'user', content: redact(withHint(prompt, schemaHint)) }],
    temperature: 0,
    max_tokens: MAX_TOKENS,
  };
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), timeoutMs);
  let data;
  try {
    const res = await fetchFn(provider.endpoint, { method: 'POST', headers, body: JSON.stringify(body), signal: controller.signal });
    if (!res.ok) {
      await res.text?.().catch(() => {}); // drained, never read: error bodies may quote the key
      return fail(`http-${res.status}`, { model: usedModel, request: { url: provider.endpoint, headers } });
    }
    try { data = await res.json(); } catch (err) {
      return fail(controller.signal.aborted || err?.name === 'AbortError' ? 'timeout' : 'bad-output');
    }
  } catch (err) {
    return fail(controller.signal.aborted || err?.name === 'AbortError' ? 'timeout' : 'network');
  } finally {
    clearTimeout(timer);
  }
  const content = data?.choices?.[0]?.message?.content;
  if (typeof content !== 'string') return fail('bad-output');
  const value = extractJSON(content);
  return value ? { ok: true, value, provider: provider.id, model: usedModel } : fail('no-json');
}

const HUNK_RE = /^@@ -\d+(?:,\d+)? \+(\d+)(?:,(\d+))? @@/gm;
const HUNK_HEAD_RE = /^@@ -(\d+)(?:,\d+)? \+(\d+)(?:,\d+)? @@/;
const DIFF_LINES_MAX = 3000;

// The new-side line ranges a unified diff (--unified=0) touched, both ends included: [{from, to}].
// A hunk that only removes lines (+N,0) has nothing to mark on the new side.
export function changedRanges(diff) {
  const changes = [];
  for (const m of diff.matchAll(HUNK_RE)) {
    const from = Number(m[1]);
    const count = m[2] === undefined ? 1 : Number(m[2]);
    if (count > 0) changes.push({ from, to: from + count });
  }
  return changes;
}

export const lineCount = (text) => (text.match(/\n/g)?.length ?? 0) + (text && !text.endsWith('\n') ? 1 : 0);

// Unified diff text to hunks of lines that start with ' ', '+' or '-'. Past DIFF_LINES_MAX lines the rest is left
// out and cut says so.
export function hunksOf(diff) {
  const hunks = [];
  let left = DIFF_LINES_MAX;
  let cut = false;
  for (const line of diff.split('\n')) {
    const head = HUNK_HEAD_RE.exec(line);
    if (head) hunks.push({ oldStart: Number(head[1]), newStart: Number(head[2]), lines: [] });
    else if (hunks.length && /^[ +-]/.test(line)) {
      if (left > 0) {
        hunks.at(-1).lines.push(line.replace(/\r$/, ''));
        left--;
      } else cut = true;
    }
  }
  return { hunks, cut };
}

// Inherited CLAUDE* variables would tag the child as a VS Code conversation of the parent session.
export const cleanEnv = (env) => Object.fromEntries(Object.entries(env).filter(([k]) => !/^(CLAUDE|MCP_CONNECTION_NONBLOCKING$)/i.test(k)));

// `claude -p --output-format json` prints one envelope: {result, is_error, total_cost_usd, ...}.
export function parseEnvelope(stdout) {
  const lines = stdout.trim().split(/\r?\n/);
  for (const text of [stdout.trim(), lines.at(-1)]) {
    try {
      const parsed = JSON.parse(text);
      if (parsed && typeof parsed === 'object' && 'result' in parsed) return parsed;
    } catch { /* try the last line: some builds print warnings first */ }
  }
  return null;
}

// Models wrap JSON in prose or code fences despite being told not to. The helper providers reuse it.
export function extractJSON(text) {
  const fenced = /```(?:json)?\s*([\s\S]*?)```/i.exec(text)?.[1];
  for (const candidate of [fenced, text.slice(text.indexOf('{'), text.lastIndexOf('}') + 1)]) {
    if (!candidate) continue;
    try {
      const value = JSON.parse(candidate.trim());
      if (value && typeof value === 'object') return value;
    } catch { /* next candidate */ }
  }
  return null;
}

// The envelope's answer as {ok, value, costUSD} or {ok: false, error, costUSD}.
export function readReply(stdout) {
  const envelope = parseEnvelope(stdout ?? '');
  if (!envelope) return { ok: false, error: 'bad-output', costUSD: 0 };
  const costUSD = Number(envelope.total_cost_usd) || 0;
  if (envelope.is_error) return { ok: false, error: 'claude-error', costUSD };
  const value = extractJSON(String(envelope.result ?? ''));
  return value ? { ok: true, value, costUSD } : { ok: false, error: 'no-json', costUSD };
}

import { timingSafeEqual } from 'node:crypto';

const COOKIE = 'sm_token';
const WRITE_METHODS = new Set(['POST', 'PUT', 'PATCH', 'DELETE']);
const LOOPBACK_ADDRESSES = new Set(['127.0.0.1', '::1', '::ffff:127.0.0.1']);
const LOOPBACK_HOST_RE = /^(127\.0\.0\.1|localhost|\[::1\])(:\d+)?/i;

export function sameToken(given, token) {
  if (typeof given !== 'string' || typeof token !== 'string') return false;
  const a = Buffer.from(given);
  const b = Buffer.from(token);
  return a.length === b.length && timingSafeEqual(a, b);
}

export function cookieToken(req) {
  for (const part of String(req.headers.cookie ?? '').split(';')) {
    const [name, ...rest] = part.trim().split('=');
    if (name === COOKIE) return rest.join('=');
  }
  return null;
}

export const tokenCookie = (token) => `${COOKIE}=${token}; HttpOnly; SameSite=Strict; Path=/; Max-Age=31536000`;

// A browser page on another site can point a name at 127.0.0.1 (DNS rebinding): only a loopback Host counts as local.
export const isLocal = (address, host) => LOOPBACK_ADDRESSES.has(address) && LOOPBACK_HOST_RE.test(String(host ?? ''));

function sameOrigin(req) {
  try {
    return Boolean(req.headers.host) && new URL(req.headers.origin).host === req.headers.host;
  } catch {
    return false;
  }
}

// → {status: 200} to go on, {status: 302, cookie, location} after ?k=, or {status: 401|403}.
export function authorize(req, url, { token, address }) {
  const fromCookie = sameToken(cookieToken(req), token);
  if (WRITE_METHODS.has(req.method)) {
    if (req.headers['x-session-map'] !== '1' || !sameOrigin(req)) return { status: 403 };
    return fromCookie ? { status: 200 } : { status: 401 };
  }
  const k = url.searchParams.get('k');
  if (k !== null) {
    if (!sameToken(k, token)) return { status: 401 };
    url.searchParams.delete('k');
    return { status: 302, cookie: tokenCookie(token), location: `${url.pathname}${url.search}` };
  }
  // Local reads are open, but the cookie only comes from ?k=.
  return fromCookie || isLocal(address, req.headers.host) ? { status: 200 } : { status: 401 };
}

import { chmodSync, mkdirSync, renameSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';
import { log } from '../log.mjs';
import { readJsonFile } from '../store.mjs';
import { providerOf } from './providers.mjs';

const KEY_MIN = 10;
const KEY_MAX = 400;
const PRINTABLE = /^[\x21-\x7E]+$/;

export const keysFile = (smDir) => join(smDir, 'ai-keys.json');

function writePrivate(path, text) {
  const tmp = `${path}.${process.pid}.tmp`;
  writeFileSync(tmp, text, { mode: 0o600 });
  renameSync(tmp, path);
  try { chmodSync(path, 0o600); } catch { /* Windows: the user's profile folder already keeps it private */ }
}

function readStore(smDir) {
  const stored = readJsonFile(keysFile(smDir), null);
  const keys = stored?.keys && typeof stored.keys === 'object' && !Array.isArray(stored.keys) ? stored.keys : {};
  return { version: 1, keys: Object.fromEntries(Object.entries(keys).filter(([id, k]) => providerOf(id) && typeof k?.data === 'string')) };
}

// null when the key may be stored, else a short reason.
export function validateKey(provider, key) {
  if (!providerOf(provider)) return 'unknown-provider';
  if (typeof key !== 'string' || key.length < KEY_MIN || key.length > KEY_MAX || !PRINTABLE.test(key)) return 'invalid-key';
  return null;
}

// backend.seal locks the key (DPAPI on Windows, AES-256-GCM elsewhere). Nothing here ever logs, returns or throws a
// key; the page only ever sees its last four characters.
export async function saveKey(smDir, provider, key, { backend, now = () => new Date().toISOString() } = {}) {
  const invalid = validateKey(provider, key);
  if (invalid) return { ok: false, error: invalid };
  let data;
  try {
    data = await backend.seal(key);
  } catch {
    log('warn', 'ai-key-seal-failed', { provider, scheme: backend.scheme });
  }
  const store = readStore(smDir);
  const entry = { scheme: backend.scheme, data, last4: key.slice(-4), savedAt: now() };
  store.keys[provider] = entry;
  mkdirSync(smDir, { recursive: true });
  writePrivate(keysFile(smDir), JSON.stringify(store, null, 1));
  return { ok: true, key: { provider, set: true, last4: entry.last4, savedAt: entry.savedAt } };
}

import { log } from '../log.mjs';

const HOUR = 60 * 60 * 1000;

// Background calls to the user's own claude, capped per hour so a busy map never burns through the owner's plan.
// Several parts of the page ask at the same time.
export class CappedRunner {
  #run;
  #now;
  #max;
  #calls = [];
  #pending = 0;

  constructor({ run, now = Date.now, maxCallsPerHour = 30 }) {
    this.#run = run;
    this.#now = now;
    this.#max = maxCallsPerHour;
  }

  async ask(prompt, options = {}) {
    const now = this.#now();
    this.#calls = this.#calls.filter((ts) => now - ts < HOUR);
    if (this.#calls.length >= this.#max) {
      log('warn', 'ai-rate-limited', { calls: this.#calls.length });
      return { ok: false, error: 'rate-limited' };
    }
    this.#pending++;
    try {
      const res = await this.#run(prompt, options);
      this.#calls.push(now);
      return res;
    } finally {
      this.#pending--;
    }
  }

  status() {
    const now = this.#now();
    return { pending: this.#pending, lastHour: this.#calls.filter((ts) => now - ts < HOUR).length, max: this.#max };
  }
}

// The owner's own word on a conversation: the project and part it belongs to and the title it goes by. It wins over
// every automatic rule and teaches the AI placer. One small file: {sessionId: {root?, partId?, title?}}.
import { join } from 'node:path';
import { readJsonFile, writeAtomic } from './store.mjs';

export const TITLE_MAX = 120;
const UUID_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

const fileOf = (smDir) => join(smDir, 'placements.json');

function clean(entry) {
  if (!entry || typeof entry !== 'object' || Array.isArray(entry)) return null;
  const out = {};
  if (typeof entry.root === 'string' && entry.root) out.root = entry.root;
  if (entry.partId === null || (typeof entry.partId === 'string' && entry.partId)) out.partId = entry.partId;
  if (typeof entry.title === 'string' && entry.title.trim()) out.title = entry.title.trim().slice(0, TITLE_MAX);
  return Object.keys(out).length ? out : null;
}

export function readPlacements(smDir) {
  const stored = readJsonFile(fileOf(smDir), {});
  const out = {};
  if (!stored || typeof stored !== 'object' || Array.isArray(stored)) return out;
  for (const [id, entry] of Object.entries(stored)) {
    const ok = UUID_RE.test(id) && clean(entry);
    if (ok) out[id] = ok;
  }
  return out;
}

// patch: root (the target project's folder), partId (a part id, or null for "no part"), title ('' gives the automatic one
// back). A field left out keeps what was there.
export function setPlacement(smDir, sessionId, patch) {
  const all = readPlacements(smDir);
  const next = { ...all[sessionId] };
  if ('root' in patch) next.root = patch.root;
  if ('partId' in patch) next.partId = patch.partId;
  if ('title' in patch) next.title = patch.title;
  const entry = clean(next);
  if (entry) all[sessionId] = entry;
  else delete all[sessionId];
  writeAtomic(fileOf(smDir), `${JSON.stringify(all)}\n`);
  return entry;
}

// What the map spent today on its AI helpers, per provider, so a helper stops for the day once its provider reaches
// the owner's daily cap. One helper call usually costs a small fraction of a cent.
const localDay = (ms) => {
  const d = new Date(ms);
  return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;
};
const round6 = (n) => Math.round(n * 1e6) / 1e6;

export class SpendBook {
  #spent;

  // stored: what toJSON() gave the last time, read back from session-map's own folder.
  constructor(stored = null) {
    const ok = stored && typeof stored.day === 'string' && Number.isFinite(stored.usd);
    this.#spent = ok ? { day: stored.day, usd: stored.usd, byProvider: { ...stored.byProvider } } : { day: '', usd: 0, byProvider: {} };
  }

  spend(nowMs, provider, costUSD = 0) {
    const day = localDay(nowMs);
    if (this.#spent.day !== day) this.#spent = { day, usd: 0, byProvider: {} };
    const booked = Number.isFinite(costUSD) ? Math.round(costUSD * 100) / 100 : 0;
    this.#spent.usd += booked;
    this.#spent.byProvider[provider] = (this.#spent.byProvider[provider] ?? 0) + booked;
  }

  spentToday(provider, nowMs) {
    if (this.#spent.day !== localDay(nowMs)) return 0;
    return round6(this.#spent.byProvider[provider] ?? 0);
  }

  // True once the provider's spend today reaches the cap: the helper rests until tomorrow.
  overCap(provider, nowMs, dailyUSD) {
    return this.spentToday(provider, nowMs) >= dailyUSD;
  }

  toJSON() {
    return { day: this.#spent.day, usd: round6(this.#spent.usd), byProvider: { ...this.#spent.byProvider } };
  }
}

import { readFileSync } from 'node:fs';
import { join } from 'node:path';
import { log } from './log.mjs';
import { normalizePath } from './paths.mjs';

const GLOBAL_KEYS = ['budget', 'currency', 'prices'];
const DEFAULTS = { roadmap: 'docs/roadmap.md', decisions: { heading: 'Decisions', pendingWhen: '[ ]' } };

function readJson(path) {
  let text;
  try {
    text = readFileSync(path, 'utf8');
  } catch (err) {
    if (err.code !== 'ENOENT') log('warn', 'config-read-failed', { path, code: err.code });
    return {};
  }
  try {
    const parsed = JSON.parse(text);
    return parsed && typeof parsed === 'object' && !Array.isArray(parsed) ? parsed : {};
  } catch {
    log('warn', 'config-invalid-json', { path });
    return {};
  }
}

// Precedence, lowest to highest: the defaults, <root>/.claude/session-map.json, then the user's per-project entry.
// budget/currency/prices are machine-wide, so they only come from the user's file. Runs for every project on each poll.
export function loadConfig(root, smDir) {
  const project = readJson(join(root, '.claude', 'session-map.json'));
  const user = readJson(join(smDir, 'config.json'));
  const perProject = user.projects?.[normalizePath(root)] ?? {};
  const config = Object.assign(DEFAULTS, project, perProject);
  for (const key of GLOBAL_KEYS) if (user[key] !== undefined) config[key] = user[key];
  // Hand-written files: a wrong type here would otherwise throw on every poll.
  if (typeof config.roadmap !== 'string') delete config.roadmap;
  const d = config.decisions;
  if (d !== undefined && (typeof d?.heading !== 'string' || typeof d?.pendingWhen !== 'string')) delete config.decisions;
  return config;
}

import { spawn } from 'node:child_process';
import { log } from './log.mjs';

const psQuote = (s) => `"${String(s).replaceAll('"', '\`"')}"`;
const shQuote = (s) => `'${String(s).replaceAll("'", "'\\''")}'`;
const appleString = (s) => s.replaceAll('\\', '\\\\').replaceAll('"', '\\"');

function detach(spawner, cmd, args, cwd) {
  const child = spawner(cmd, args, { cwd, detached: true, stdio: 'ignore', windowsHide: false });
  child.on?.('error', (err) => log('warn', 'launch-failed', { cmd, code: err.code }));
  child.unref?.();
  return { cmd, args };
}

// Opens a terminal in cwd running argv (an empty argv is a plain shell). The values come from the map: a folder path,
// a git branch name, a conversation id; they may hold any character such names allow.
export function openTerminal(cwd, argv, { platform = process.platform, spawner = spawn } = {}) {
  if (platform === 'win32') {
    return detach(spawner, 'powershell.exe', argv.length ? ['-NoExit', '-Command', `& ${argv.map(psQuote).join(' ')}`] : ['-NoExit'], cwd);
  }
  if (platform === 'darwin') {
    const script = [`cd ${shQuote(cwd)}`, ...(argv.length ? [argv.map(shQuote).join(' ')] : [])].join(' && ');
    return detach(spawner, 'osascript', ['-e', `tell application "Terminal" to do script "${appleString(script)}"`], cwd);
  }
  return detach(spawner, 'x-terminal-emulator', argv.length ? ['-e', ...argv] : [], cwd);
}

// A claude conversation picked up again in a new terminal, in the folder it ran in.
export function resumeInTerminal(cwd, sessionId, options) {
  return openTerminal(cwd, ['claude', '--resume', sessionId], options);
}

// A new conversation on a branch, named after it so remote control lists it under that name.
export function startOnBranch(cwd, branch, options) {
  return openTerminal(cwd, ['claude', '--remote-control', branch], options);
}

import { realpathSync } from 'node:fs';
import { isAbsolute, relative, resolve, sep } from 'node:path';

const GIT_NAME_RE = /^(\.git|git~\d+)$/i;
const DRIVE_RE = /^[a-z]:/i;

// Path segments of a request, or null when any of them could leave the project or reach .git.
// Windows quietly drops trailing dots and spaces ("..", ".git.") and understands "name:stream" and 8.3 names, hence the extra checks.
function segmentsOf(rel) {
  if (typeof rel !== 'string' || !rel || rel.includes('\0')) return null;
  let decoded = rel;
  try { decoded = decodeURIComponent(rel); } catch { /* a literal % in a file name */ }
  let segments = null;
  for (const form of new Set([rel, decoded])) {
    const slashed = form.replaceAll('\\', '/');
    if (slashed.startsWith('/') || DRIVE_RE.test(slashed)) return null;
    const parts = slashed.split('/').filter(Boolean);
    for (const part of parts) {
      const bare = part.replace(/[. ]+$/, '');
      if (!bare || part.includes(':') || GIT_NAME_RE.test(bare)) return null;
    }
    segments ??= parts;
  }
  return segments.length ? segments : null;
}

const inside = (root, path) => {
  const rel = relative(root, path);
  return rel !== '' && !rel.startsWith('..') && !isAbsolute(rel) && !rel.split(sep).some((s) => GIT_NAME_RE.test(s));
};

// The absolute path of a file under root, or null. A link that leads out of the root is refused by following it.
export function safeResolve(root, rel) {
  const segments = segmentsOf(rel);
  if (!segments) return null;
  const abs = resolve(root, ...segments);
  if (!inside(root, abs)) return null;
  let real;
  try {
    real = realpathSync(abs);
  } catch {
    return abs;
  }
  return inside(realpathSync(root), real) ? real : null;
}

import { createHash } from 'node:crypto';
import { join } from 'node:path';
import { readJsonFile, writeAtomic } from '../store.mjs';

const CACHE_MAX = 1000;
const hashOf = (key) => createHash('sha1').update(JSON.stringify(key)).digest('hex');

// The AI's answers, cached by content in smDir/ai-cache.json so the same question is never paid for twice.
// Past the limit, the answers stored longest ago are dropped first.
export class AnswerCache {
  #file;
  #now;
  #max;
  #cache;

  constructor({ smDir, now = Date.now, max = CACHE_MAX }) {
    this.#file = join(smDir, 'ai-cache.json');
    this.#now = now;
    this.#max = max;
    const stored = readJsonFile(this.#file, null);
    this.#cache = stored?.cache && typeof stored.cache === 'object' ? stored.cache : {};
  }

  get(key) {
    const hit = this.#cache[hashOf(key)];
    return hit ? { ok: true, value: hit.value, costUSD: 0, cached: true } : null;
  }

  set(key, value) {
    this.#cache[hashOf(key)] = { value, at: this.#now() };
    this.#save();
  }

  get size() {
    return Object.keys(this.#cache).length;
  }

  #save() {
    const entries = Object.entries(this.#cache);
    if (entries.length > this.#max) {
      entries.sort((a, b) => a[1].at - b[1].at);
      this.#cache = Object.fromEntries(entries.slice(0, this.#max));
    }
    writeAtomic(this.#file, JSON.stringify({ cache: this.#cache }));
  }
}

// What leaves the PC for an outside AI goes through here first: personal data becomes placeholders.
// Claude (the local CLI) keeps receiving the prompt as written; only the helper providers see the masked text.

// Unicode letters too: an ASCII-only local part would leave the accented half of a name out.
const EMAIL = /[\p{L}\p{N}._%+-]+@[\p{L}\p{N}-]+(?:\.[\p{L}\p{N}-]+)*\.\p{L}{2,}/gu;
const CNPJ = /\b\d{2}\.\d{3}\.\d{3}\/\d{4}-\d{2}\b/g;
const CPF = /\b\d{3}\.\d{3}\.\d{3}-\d{2}\b/g;
// A payment card: 13 to 19 digits, maybe split by spaces or dashes.
const CARD = /\b\d(?:[ -]?\d){12,18}\b/g;

// The card checksum (Luhn) keeps ordinary long numbers (ids, timestamps) out of the mask.
function luhn(digits) {
  let sum = 0;
  for (let i = 0; i < digits.length; i++) {
    let d = Number(digits[digits.length - 1 - i]);
    if (i % 2 === 0) { d *= 2; if (d > 9) d -= 9; }
    sum += d;
  }
  return sum % 10 === 0;
}

export function maskPersonal(text) {
  let out = String(text ?? '');
  out = out.replace(EMAIL, '[email]');
  out = out.replace(CNPJ, '[cnpj]').replace(CPF, '[cpf]');
  out = out.replace(CARD, (m) => (luhn(m.replace(/\D/g, '')) ? '[card]' : m));
  return out;
}

// How many placeholders a masked text holds, for the log line that says what was hidden (never the values).
export function maskedCounts(masked) {
  const counts = {};
  for (const [, kind] of masked.matchAll(/\[(email|cnpj|cpf|card)\]/g)) counts[kind] = (counts[kind] ?? 0) + 1;
  return counts;
}

import { readFileSync } from 'node:fs';

const PER_MILLION = 1_000_000;
const FIELDS = ['input', 'output', 'cacheWrite5m', 'cacheWrite1h', 'cacheRead'];

// Keys starting with "_" (_asOf, _note) are metadata, not models.
export function loadPrices(overrides = {}) {
  const shipped = JSON.parse(readFileSync(new URL('./prices.json', import.meta.url), 'utf8'));
  return Object.fromEntries(Object.entries({ ...shipped, ...overrides }).filter(([k]) => !k.startsWith('_')));
}

// "claude-opus-5-5-20261001" matches key "claude-opus-5-5"; the longest key wins over "claude-opus-5".
export function priceFor(model, prices) {
  let best = null;
  for (const key of Object.keys(prices)) {
    if ((model === key || model.startsWith(`${key}-`)) && (best === null || key.length < best.length)) best = key;
  }
  return best === null ? null : prices[best];
}

// rows: token counts per model, as the transcripts record them. A model with no price is listed, never guessed.
export function costOf(rows, prices) {
  let usd = 0;
  const unpriced = new Set();
  for (const row of rows) {
    const price = priceFor(row.model ?? '', prices);
    if (!price) {
      unpriced.add(row.model ?? 'unknown');
      continue;
    }
    for (const field of FIELDS) usd += ((row[field] ?? 0) * (price[field] ?? 0)) / PER_MILLION;
  }
  return { usd, unpriced: [...unpriced] };
}

export function toCurrency(usd, currency) {
  return currency ? usd * currency.rate : usd;
}

import { log } from '../log.mjs';

// A cheaper AI takes the bulk work when the owner turned it on; whatever goes wrong there, the call falls back to Claude.
export class HelperRouter {
  #askClaude;
  #apiRun;
  #settings;
  #keyOf;

  // askClaude(prompt, schemaHint) and apiRun(prompt, options) both resolve to {ok, value?, error?, costUSD?}.
  constructor({ askClaude, apiRun, settings, keyOf }) {
    this.#askClaude = askClaude;
    this.#apiRun = apiRun;
    this.#settings = settings;
    this.#keyOf = keyOf;
  }

  // The helper to use for this call, with its key, or null: turned off, or no key stored.
  async #helperFor() {
    const settings = this.#settings();
    if (!settings?.enabled || !settings.provider) return null;
    const key = await Promise.resolve().then(() => this.#keyOf(settings.provider)).catch(() => null);
    return key ? { ...settings, key } : null;
  }

  // A thrown error is not logged: its message could quote the request, key included.
  async #askHelper(helper, prompt, schemaHint) {
    try {
      return this.#apiRun(prompt, { provider: helper.provider, model: helper.model, key: helper.key, schemaHint });
    } catch {
      return { ok: false, error: 'helper-threw' };
    }
  }

  async answer(prompt, schemaHint) {
    const helper = await this.#helperFor();
    if (!helper) return this.#askClaude(prompt, schemaHint);
    const fromHelper = await this.#askHelper(helper, prompt, schemaHint);
    if (fromHelper.ok) return fromHelper;
    log('warn', 'ai-helper-fallback', { provider: helper.provider, error: fromHelper.error });
    const fromClaude = await this.#askClaude(prompt, schemaHint);
    return { ...fromClaude, costUSD: (fromHelper.costUSD ?? 0) + (fromClaude.costUSD ?? 0) };
  }
}

const PER_MILLION = 1_000_000;
const DAY_MS = 86_400_000;
const FIELDS = ['input', 'output', 'cacheWrite5m', 'cacheWrite1h', 'cacheRead'];

// "claude-opus-5-5-20261001" matches key "claude-opus-5-5"; the longest key wins over "claude-opus-5".
export function priceFor(model, prices) {
  let best = null;
  for (const key of Object.keys(prices)) {
    if ((model === key || model.startsWith(`${key}-`)) && (best === null || key.length > best.length)) best = key;
  }
  return best === null ? null : prices[best];
}

export function costOf(rows, prices) {
  let usd = 0;
  const unpriced = new Set();
  for (const row of rows) {
    const price = priceFor(row.model ?? '', prices);
    if (!price) {
      unpriced.add(row.model ?? 'unknown');
      continue;
    }
    for (const field of FIELDS) usd += ((row[field] ?? 0) * (price[field] ?? 0)) / PER_MILLION;
  }
  return { usd, unpriced: [...unpriced] };
}

// "Today" starts at local midnight; 7 and 30 days are rolling windows back from now.
export function windowed(rows, now, prices) {
  const dayStart = new Date(now.getFullYear(), now.getMonth(), now.getDate()).getTime();
  const cutoffs = { today: dayStart, d7: now.getTime() - 7 * DAY_MS, d30: now.getTime() - 30 * DAY_MS };
  const out = {};
  for (const [name, from] of Object.entries(cutoffs)) {
    out[name] = costOf(rows.filter((r) => Date.parse(r.ts) >= from), prices).usd;
  }
  return out;
}

// The cost of each local day ("YYYY-MM-DD"), so the page can add up any range the owner picks. A day that costs
// nothing is left out.
export function dailyCost(rows, prices) {
  const byDay = new Map();
  for (const r of rows) {
    const d = new Date(r.ts);
    if (Number.isNaN(d.getTime())) continue;
    const key = `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;
    if (!byDay.has(key)) byDay.set(key, []);
    byDay.get(key).push(r);
  }
  const out = {};
  for (const [day, list] of [...byDay].sort(([a], [b]) => a.localeCompare(b))) {
    const usd = costOf(list, prices).usd;
    if (usd > 0) out[day] = Math.round(usd * 1e6) / 1e6;
  }
  return out;
}

const PER_MILLION = 1_000_000;
const FIELDS = ['input', 'output', 'cacheWrite5m', 'cacheWrite1h', 'cacheRead'];

// prices: {model: {input, output, ...}} in US$ per million tokens; an exact model name only.
export function costOf(rows, prices) {
  let usd = 0;
  const unpriced = new Set();
  for (const row of rows) {
    const price = Object.hasOwn(prices, row.model ?? '') ? prices[row.model] : null;
    if (!price) {
      unpriced.add(row.model ?? 'unknown');
      continue;
    }
    for (const field of FIELDS) usd += ((row[field] ?? 0) * (price[field] ?? 0)) / PER_MILLION;
  }
  return { usd, unpriced: [...unpriced] };
}

const pad2 = (n) => String(n).padStart(2, '0');

// The local calendar day of a moment, "YYYY-MM-DD".
const dayKey = (d) => `${d.getFullYear()}-${pad2(d.getMonth() + 1)}-${pad2(d.getDay())}`;

// The cost of each local day, so the page can add up any range the owner picks. A day that costs nothing is left out.
export function dailyCost(rows, prices) {
  const byDay = new Map();
  for (const r of rows) {
    const d = new Date(r.ts);
    if (Number.isNaN(d.getTime())) continue;
    const key = dayKey(d);
    if (!byDay.has(key)) byDay.set(key, []);
    byDay.get(key).push(r);
  }
  const out = {};
  for (const [day, list] of [...byDay].sort(([a], [b]) => a.localeCompare(b))) {
    const usd = costOf(list, prices).usd;
    if (usd > 0) out[day] = Math.round(usd * 1e6) / 1e6;
  }
  return out;
}

// The days between from and to ("YYYY-MM-DD", both included) added up.
export function rangeCost(daily, from, to) {
  let usd = 0;
  for (const [day, value] of Object.entries(daily)) if (day >= from && day <= to) usd += value;
  return Math.round(usd * 1e6) / 1e6;
}
